import json

solution = np.array([list(map(int, line.split())) for line in grid_str.strip().split('\n')])
non_8_mask = solution != 8
labeled_array, num_features = ndimage.label(non_8_mask)

def get_dominant(subgrid):
    vals = [v for v in subgrid.flat if v != 8]
    if not vals:
        return 8
    counts = {}
    for v in vals:
        counts[v] = counts.get(v, 0) + 1
    return max(counts.keys(), key=lambda k: (counts[k], k))

output = solution.copy()
for i in range(1, num_features + 1):
    positions = np.argwhere(labeled_array == i)
    min_r, max_r = int(positions[:, 0].min()), int(positions[:, 0].max())
    min_c, max_c = int(positions[:, 1].min()), int(positions[:, 1].max())

    subgrid = solution[min_r:max_r+1, min_c:max_c+1]
    h, w = subgrid.shape

    dominant = get_dominant(subgrid)
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            output[r, c] = dominant

# Submit
action = {"action": "submit", "grid": output.tolist()}
print(json.dumps(action))

